/**
 * Intelligent cache with TTL per type
 * Prevents hammering APIs, serves stale data during outages
 */

const store = new Map();

export function get(key) {
  const entry = store.get(key);
  if (!entry) return null;
  if (Date.now() > entry.expires) {
    store.delete(key);
    return null;
  }
  return entry.value;
}

export function set(key, value, ttlSeconds = 60) {
  store.set(key, {
    value,
    expires: Date.now() + ttlSeconds * 1000,
    created: Date.now()
  });
}

export function invalidate(key) {
  store.delete(key);
}

export function invalidatePrefix(prefix) {
  for (const key of store.keys()) {
    if (key.startsWith(prefix)) store.delete(key);
  }
}

export function stats() {
  let active = 0, expired = 0;
  const now = Date.now();
  for (const [, entry] of store) {
    if (now > entry.expires) expired++;
    else active++;
  }
  return { active, expired, total: store.size };
}

export function clear() {
  store.clear();
}

mcp-server/lib/job-manager.js:
/**
 * Job Manager — central registry for all background tasks
 *
 * Every background job (enricher, bars-worker, rolling-scanner, monitor…)
 * registers here. The user can start/stop/pause/resume/schedule any job
 * via MCP tools and see the full state in one call.
 *
 * Schedule formats (passed to setSchedule / register):
 *   { every: '5min' }          every 5 minutes
 *   { every: '30min' }
 *   { every: '1h' }
 *   { every: '6h' }
 *   { every: '1d' }
 *   { daily: '09:00' }         every day at 09:00 UTC
 *   { daily: '09:00', weekday: 1 } Monday only (0=Sun … 6=Sat)
 *
 * Job lifecycle:
 *   idle → start() → running → stop() → idle
 *                  → pause() → paused → resume() → running
 *   Any state → error (on uncaught run error)
 */

// ─── Store ────────────────────────────────────────────────────────────────────

const _jobs = new Map();  // id → job

// ─── Public: register ─────────────────────────────────────────────────────────

/**
 * Register a job.
 *
 * @param {string} id        Unique identifier (e.g. 'enricher', 'bars_worker')
 * @param {object} def
 *   name        {string}
 *   description {string}  optional
 *   type        {string}  'periodic' | 'scanner' | 'oneshot'
 *   fn          {async function(job)} — one cycle of work
 *   stopFn      {function}  optional — called on stop()
 *   pauseFn     {function}  optional — called on pause()
 *   resumeFn    {function}  optional — called on resume()
 *   schedule    {object}    optional initial schedule
 *   autoStart   {boolean}   if true + schedule given, starts automatically
 */
export function register(id, def) {
  if (_jobs.has(id)) return _jobs.get(id);

  const job = {
    id,
    name:        def.name        || id,
    description: def.description || '',
    type:        def.type        || 'periodic',
    status:      'idle',
    schedule:    def.schedule    || null,
    _fn:         def.fn,
    _stopFn:     def.stopFn   || null,
    _pauseFn:    def.pauseFn  || null,
    _resumeFn:   def.resumeFn || null,
    // Runtime state
    _timer:      null,
    _running:    false,
    createdAt:   new Date().toISOString(),
    startedAt:   null,
    lastRun:     null,
    nextRun:     null,
    runCount:    0,
    errorCount:  0,
    lastError:   null,
    lastResult:  null,
    // Scanner extras (populated by rolling-scanner)
    progress:    null,
  };

  _jobs.set(id, job);

  if (def.schedule && def.autoStart !== false) {
    _applySchedule(job);
  }

  return job;
}

// ─── Public: control ──────────────────────────────────────────────────────────

export function start(id) {
  const job = _get(id);
  if (job.status === 'running') return _pub(job);
  _clearTimer(job);
  job.status    = 'running';
  job.startedAt = new Date().toISOString();
  _runCycle(job);
  return _pub(job);
}

export function stop(id) {
  const job = _get(id);
  _clearTimer(job);
  if (job._stopFn) try { job._stopFn(); } catch {}
  job.status  = 'idle';
  job.nextRun = null;
  return _pub(job);
}

export function pause(id) {
  const job = _get(id);
  _clearTimer(job);
  if (job._pauseFn) try { job._pauseFn(); } catch {}
  if (job.status !== 'idle') job.status = 'paused';
  job.nextRun = null;
  return _pub(job);
}

export function resume(id) {
  const job = _get(id);
  if (job.status !== 'paused') return _pub(job);
  if (job._resumeFn) try { job._resumeFn(); } catch {}
  job.status = 'scheduled';
  if (job.schedule) _applySchedule(job);
  else _runCycle(job);
  return _pub(job);
}

export function runNow(id) {
  const job = _get(id);
  _clearTimer(job);
  job.status = 'running';
  _runCycle(job);
  return _pub(job);
}

export function remove(id) {
  const job = _jobs.get(id);
  if (!job) return false;
  _clearTimer(job);
  if (job._stopFn) try { job._stopFn(); } catch {}
  _jobs.delete(id);
  return true;
}

// ─── Public: scheduling ───────────────────────────────────────────────────────

/**
 * Set or update the schedule for a job.
 * @param {string} id
 * @param {object|null} schedule   null = remove schedule (idle after current run)
 */
export function setSchedule(id, schedule) {
  const job = _get(id);
  _clearTimer(job);
  job.schedule = schedule || null;
  if (job.schedule && job.status !== 'paused') {
    _applySchedule(job);
  } else if (!job.schedule) {
    job.status  = 'idle';
    job.nextRun = null;
  }
  return _pub(job);
}

// ─── Public: query ────────────────────────────────────────────────────────────

export function list() {
  return [..._jobs.values()].map(_pub);
}

export function get(id) {
  return _jobs.has(id) ? _pub(_jobs.get(id)) : null;
}

export function getInternal(id) {
  return _jobs.get(id) ?? null;
}

// ─── Internal: run cycle ──────────────────────────────────────────────────────

async function _runCycle(job) {
  if (job._running) return;
  job._running = true;
  job.status   = 'running';
  job.lastRun  = new Date().toISOString();
  job.runCount++;

  try {
    const result = await job._fn(job);
    job.lastResult = result ?? null;
    job.lastError  = null;
  } catch (e) {
    job.errorCount++;
    job.lastError = { message: e.message, at: new Date().toISOString() };
    job.status    = 'error';
    console.error(`[JobManager] ${job.id} error: ${e.message}`);
  }

  job._running = false;

  // Re-schedule if still active
  if (job.status !== 'idle' && job.status !== 'paused' && job.schedule) {
    _applySchedule(job);
  } else if (job.status === 'running') {
    job.status = 'idle';
  }
}

// ─── Internal: scheduling ─────────────────────────────────────────────────────

function _applySchedule(job) {
  _clearTimer(job);
  const ms = _scheduleToMs(job.schedule);
  if (!ms || ms <= 0) return;

  job.nextRun = new Date(Date.now() + ms).toISOString();
  job.status  = job.status === 'running' ? 'running' : 'scheduled';

  job._timer = setTimeout(async () => {
    job._timer = null;
    await _runCycle(job);
  }, ms);
}

/** Parse schedule object → milliseconds until next run */
function _scheduleToMs(sched) {
  if (!sched) return null;

  // { every: '5min' | '1h' | '30s' | '1d' }
  if (sched.every) {
    const m = String(sched.every).trim().match(/^(\d+(?:\.\d+)?)\s*(s|sec|min|h|hr|hour|d|day)s?$/i);
    if (!m) return null;
    const n    = parseFloat(m[1]);
    const unit = m[2].toLowerCase();
    const mul  = { s:1000, sec:1000, min:60_000, h:3_600_000, hr:3_600_000, hour:3_600_000, d:86_400_000, day:86_400_000 };
    return Math.round(n * (mul[unit] ?? 60_000));
  }

  // { daily: '09:00', weekday: 1 }  (0=Sun…6=Sat, omit = every day)
  if (sched.daily) {
    const [h, min] = sched.daily.split(':').map(Number);
    const now  = new Date();
    const next = new Date(now);
    next.setUTCHours(h, min, 0, 0);
    if (next <= now) next.setUTCDate(next.getUTCDate() + 1);
    // weekday filter — advance until correct day
    if (sched.weekday != null) {
      while (next.getUTCDay() !== sched.weekday) next.setUTCDate(next.getUTCDate() + 1);
    }
    return next.getTime() - now.getTime();
  }

  // { intervalMs: N }
  if (sched.intervalMs) return sched.intervalMs;

  return null;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function _clearTimer(job) {
  if (job._timer) { clearTimeout(job._timer); job._timer = null; }
}

function _get(id) {
  const job = _jobs.get(id);
  if (!job) throw new Error(`Job "${id}" not found`);
  return job;
}

/** Public-safe job snapshot (no internal refs) */
function _pub(job) {
  const { _fn, _stopFn, _pauseFn, _resumeFn, _timer, _running, ...pub } = job;
  return pub;
}

// ─── Format helpers (for display) ────────────────────────────────────────────

export function formatSchedule(sched) {
  if (!sched) return 'none';
  if (sched.every) return `every ${sched.every}`;
  if (sched.daily) {
    const days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
    return sched.weekday != null ? `every ${days[sched.weekday]} at ${sched.daily} UTC` : `daily at ${sched.daily} UTC`;
  }
  if (sched.intervalMs) return `every ${Math.round(sched.intervalMs / 60000)}min`;
  return JSON.stringify(sched);
}

mcp-server/lib/journal.js:
/**
 * Trade Journal — SQLite-backed
 * Auto-logs alert events, manual trade entries, statistics
 */

import { existsSync, mkdirSync } from 'fs';
import { dirname } from 'path';

let db = null;

// ══════════════════════════════════════
// INIT
// ══════════════════════════════════════

export async function init(dbPath = './data/journal.db') {
  try {
    const dir = dirname(dbPath);
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });

    const Database = (await import('better-sqlite3')).default;
    db = new Database(dbPath);

    db.exec(`
      CREATE TABLE IF NOT EXISTS trades (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        ticker TEXT NOT NULL,
        direction TEXT DEFAULT 'long',
        strategy TEXT,
        entry_price REAL,
        stop_price REAL,
        tp1_price REAL,
        tp2_price REAL,
        exit_price REAL,
        shares INTEGER,
        risk_pct REAL,
        r_multiple REAL,
        pnl REAL,
        pnl_pct REAL,
        status TEXT DEFAULT 'open',
        entry_date TEXT,
        exit_date TEXT,
        entry_reason TEXT,
        exit_reason TEXT,
        notes TEXT,
        emotional_state TEXT,
        screenshot_url TEXT,
        tags TEXT,
        created_at TEXT DEFAULT (datetime('now')),
        updated_at TEXT DEFAULT (datetime('now'))
      );

      CREATE TABLE IF NOT EXISTS alert_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        ticker TEXT NOT NULL,
        alert_type TEXT,
        message TEXT,
        price REAL,
        rvol REAL,
        triggered_at TEXT DEFAULT (datetime('now'))
      );

      CREATE INDEX IF NOT EXISTS idx_trades_ticker ON trades(ticker);
      CREATE INDEX IF NOT EXISTS idx_trades_status ON trades(status);
      CREATE INDEX IF NOT EXISTS idx_trades_date ON trades(entry_date);
      CREATE INDEX IF NOT EXISTS idx_alert_log_ticker ON alert_log(ticker);
    `);

    console.error('[Journal] Database initialized');
    return true;
  } catch (err) {
    console.warn('[Journal] SQLite not available, using in-memory store:', err.message);
    db = null;
    return false;
  }
}

// ══════════════════════════════════════
// TRADES CRUD
// ══════════════════════════════════════

export function addTrade(trade) {
  if (!db) return inMemoryAdd(trade);

  const stmt = db.prepare(`
    INSERT INTO trades (ticker, direction, strategy, entry_price, stop_price, tp1_price, tp2_price,
      shares, risk_pct, entry_date, entry_reason, notes, emotional_state, tags)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);

  const result = stmt.run(
    trade.ticker?.toUpperCase(), trade.direction || 'long', trade.strategy,
    trade.entry_price, trade.stop_price, trade.tp1_price, trade.tp2_price,
    trade.shares, trade.risk_pct, trade.entry_date || new Date().toISOString().split('T')[0],
    trade.entry_reason, trade.notes, trade.emotional_state,
    Array.isArray(trade.tags) ? trade.tags.join(',') : trade.tags
  );

  return { id: result.lastInsertRowid, ...trade };
}

export function closeTrade(id, { exit_price, exit_reason, notes }) {
  if (!db) return null;

  const trade = db.prepare('SELECT * FROM trades WHERE id = ?').get(id);
  if (!trade) return null;

  const pnl = trade.direction === 'long'
    ? (exit_price - trade.entry_price) * (trade.shares || 1)
    : (trade.entry_price - exit_price) * (trade.shares || 1);

  const pnl_pct = trade.direction === 'long'
    ? ((exit_price - trade.entry_price) / trade.entry_price) * 100
    : ((trade.entry_price - exit_price) / trade.entry_price) * 100;

  const risk = Math.abs(trade.entry_price - trade.stop_price);
  const r_multiple = risk > 0 ? (trade.direction === 'long' ? exit_price - trade.entry_price : trade.entry_price - exit_price) / risk : null;

  db.prepare(`
    UPDATE trades SET exit_price = ?, exit_date = datetime('now'), exit_reason = ?,
    pnl = ?, pnl_pct = ?, r_multiple = ?, status = 'closed',
    notes = COALESCE(?, notes), updated_at = datetime('now')
    WHERE id = ?
  `).run(exit_price, exit_reason, pnl, pnl_pct, r_multiple, notes, id);

  return db.prepare('SELECT * FROM trades WHERE id = ?').get(id);
}

export function getTrades(filter = {}) {
  if (!db) return inMemoryTrades;

  let sql = 'SELECT * FROM trades WHERE 1=1';
  const params = [];

  if (filter.ticker) { sql += ' AND ticker = ?'; params.push(filter.ticker.toUpperCase()); }
  if (filter.status) { sql += ' AND status = ?'; params.push(filter.status); }
  if (filter.strategy) { sql += ' AND strategy = ?'; params.push(filter.strategy); }
  if (filter.from) { sql += ' AND entry_date >= ?'; params.push(filter.from); }
  if (filter.to) { sql += ' AND entry_date <= ?'; params.push(filter.to); }

  sql += ' ORDER BY entry_date DESC';
  if (filter.limit) { sql += ' LIMIT ?'; params.push(filter.limit); }

  return db.prepare(sql).all(...params);
}

export function getTradeById(id) {
  if (!db) return null;
  return db.prepare('SELECT * FROM trades WHERE id = ?').get(id);
}

// ══════════════════════════════════════
// ALERT LOG
// ══════════════════════════════════════

export function logAlert(alert) {
  if (!db) return;
  db.prepare(`
    INSERT INTO alert_log (ticker, alert_type, message, price, rvol)
    VALUES (?, ?, ?, ?, ?)
  `).run(alert.ticker, alert.type, alert.message, alert.currentPrice, alert.rvol);
}

export function getAlertLog(limit = 100) {
  if (!db) return [];
  return db.prepare('SELECT * FROM alert_log ORDER BY triggered_at DESC LIMIT ?').all(limit);
}

// ══════════════════════════════════════
// STATISTICS
// ══════════════════════════════════════

export function getStats(filter = {}) {
  if (!db) return {};

  let where = "status = 'closed'";
  const params = [];
  if (filter.from) { where += ' AND entry_date >= ?'; params.push(filter.from); }
  if (filter.to) { where += ' AND entry_date <= ?'; params.push(filter.to); }
  if (filter.strategy) { where += ' AND strategy = ?'; params.push(filter.strategy); }

  const trades = db.prepare(`SELECT * FROM trades WHERE ${where} ORDER BY entry_date`).all(...params);

  if (trades.length === 0) return { totalTrades: 0, message: 'No closed trades yet' };

  const winners = trades.filter(t => t.pnl > 0);
  const losers = trades.filter(t => t.pnl <= 0);
  const totalPnl = trades.reduce((s, t) => s + (t.pnl || 0), 0);
  const avgWin = winners.length ? winners.reduce((s, t) => s + t.pnl, 0) / winners.length : 0;
  const avgLoss = losers.length ? losers.reduce((s, t) => s + t.pnl, 0) / losers.length : 0;
  const profitFactor = avgLoss !== 0 ? Math.abs(avgWin * winners.length / (avgLoss * losers.length)) : Infinity;
  const avgR = trades.filter(t => t.r_multiple != null).reduce((s, t) => s + t.r_multiple, 0) / trades.filter(t => t.r_multiple != null).length || 0;

  // Max drawdown
  let peak = 0, maxDD = 0, cumPnl = 0;
  for (const t of trades) {
    cumPnl += t.pnl || 0;
    if (cumPnl > peak) peak = cumPnl;
    const dd = peak - cumPnl;
    if (dd > maxDD) maxDD = dd;
  }

  return {
    totalTrades: trades.length,
    winRate: +(winners.length / trades.length * 100).toFixed(1),
    winners: winners.length,
    losers: losers.length,
    totalPnl: +totalPnl.toFixed(2),
    avgWin: +avgWin.toFixed(2),
    avgLoss: +avgLoss.toFixed(2),
    profitFactor: +profitFactor.toFixed(2),
    avgRMultiple: +avgR.toFixed(2),
    bestTrade: trades.reduce((best, t) => (!best || (t.pnl || 0) > (best.pnl || 0)) ? t : best, null),
    worstTrade: trades.reduce((worst, t) => (!worst || (t.pnl || 0) < (worst.pnl || 0)) ? t : worst, null),
    maxDrawdown: +maxDD.toFixed(2),
    byStrategy: getStatsByStrategy(trades)
  };
}

function getStatsByStrategy(trades) {
  const groups = {};
  for (const t of trades) {
    const s = t.strategy || 'unknown';
    if (!groups[s]) groups[s] = [];
    groups[s].push(t);
  }
  const result = {};
  for (const [strategy, strades] of Object.entries(groups)) {
    const w = strades.filter(t => t.pnl > 0);
    result[strategy] = {
      trades: strades.length,
      winRate: +(w.length / strades.length * 100).toFixed(1),
      totalPnl: +strades.reduce((s, t) => s + (t.pnl || 0), 0).toFixed(2)
    };
  }
  return result;
}

// In-memory fallback
const inMemoryTrades = [];
function inMemoryAdd(trade) {
  const t = { id: inMemoryTrades.length + 1, ...trade, created_at: new Date().toISOString() };
  inMemoryTrades.push(t);
  return t;
}

mcp-server/lib/local-llm.js:
/**
 * Local LLM orchestration module
 * Invokes locally-installed AI CLIs (Claude Code, Gemini CLI, etc.)
 *
 * Feature detection: only exposes tools for CLIs that exist on the machine.
 * The MCP client can be any LLM — this enables cross-model collaboration:
 *   - Gemini calling Claude for a second opinion
 *   - Claude calling Gemini for grounded web search
 *   - Cursor/Windsurf calling either for specialized analysis
 */

import { spawn, execFile } from 'child_process';
import { promisify } from 'util';

const execFileAsync = promisify(execFile);

// ── CLI definitions ──

const CLI_DEFS = {
  claude: {
    names: ['claude'],
    flag: '--version',
    buildArgs: (prompt, opts) => {
      const args = ['-p', prompt, '--output-format', 'text'];
      if (opts.model) args.push('--model', opts.model);
      if (opts.allowedTools?.length) args.push('--allowedTools', ...opts.allowedTools);
      if (opts.appendSystemPrompt) args.push('--append-system-prompt', opts.appendSystemPrompt);
      if (opts.maxTurns) args.push('--max-turns', String(opts.maxTurns));
      return args;
    },
    defaultTimeout: 180_000,
    description: 'Claude Code CLI (claude -p). Best for: code analysis, refactoring, tool-use tasks, MCP-aware queries.'
  },
  gemini: {
    names: ['gemini'],
    flag: '--version',
    buildArgs: (prompt, opts) => {
      const args = ['-p', prompt];
      if (opts.model) args.push('-m', opts.model);
      if (opts.sandbox === false) args.push('--sandbox', 'false');
      return args;
    },
    defaultTimeout: 120_000,
    description: 'Gemini CLI (gemini -p). Best for: web-grounded search, fact-checking, cross-validation, Google ecosystem data.'
  }
};

// ── State ──

const _available = {};

// ── Feature detection at startup ──

export async function detect() {
  for (const [key, def] of Object.entries(CLI_DEFS)) {
    for (const name of def.names) {
      try {
        const { stdout } = await execFileAsync(name, [def.flag], { timeout: 5000 });
        _available[key] = { binary: name, version: stdout.trim(), ...def };
        break;
      } catch {
        // Binary not found or unresponsive — skip
      }
    }
  }
  return Object.keys(_available);
}

// ── List available CLIs ──

export function available() {
  return Object.entries(_available).map(([key, def]) => ({
    key,
    binary: def.binary,
    version: def.version,
    description: def.description
  }));
}

// ── Build clean env for child process ──

function cleanEnvFor(opts = {}) {
  const env = { ...process.env, ...(opts.env || {}) };
  // Remove all Claude/Anthropic session vars to prevent nested-session detection
  for (const key of Object.keys(env)) {
    if (key.startsWith('CLAUDE') || key.startsWith('ANTHROPIC_')) delete env[key];
  }
  // Re-add API key if present (needed for Claude API access)
  if (process.env.ANTHROPIC_API_KEY) env.ANTHROPIC_API_KEY = process.env.ANTHROPIC_API_KEY;
  return env;
}

// ── Invoke a CLI using spawn (required: some CLIs hang with execFile if stdin isn't closed) ──

function spawnAsync(binary, args, { timeout, env, cwd }) {
  return new Promise((resolve, reject) => {
    let stdout = '', stderr = '';
    let killed = false;

    const child = spawn(binary, args, {
      env,
      cwd,
      stdio: ['pipe', 'pipe', 'pipe']
    });

    // Close stdin immediately — CLIs in -p mode don't need it
    child.stdin.end();

    child.stdout.on('data', d => { stdout += d; });
    child.stderr.on('data', d => { stderr += d; });

    const timer = setTimeout(() => {
      killed = true;
      child.kill('SIGTERM');
      // Force kill after 5s if SIGTERM didn't work
      setTimeout(() => child.kill('SIGKILL'), 5000);
    }, timeout);

    child.on('close', (code) => {
      clearTimeout(timer);
      if (killed) {
        reject(Object.assign(new Error('Timeout'), { killed: true, stdout, stderr }));
      } else if (code !== 0) {
        reject(Object.assign(new Error(`Exit code ${code}`), { code, stdout, stderr }));
      } else {
        resolve({ stdout, stderr });
      }
    });

    child.on('error', (err) => {
      clearTimeout(timer);
      reject(err);
    });
  });
}

// ── Invoke a local CLI ──

export async function invoke(cli, prompt, opts = {}) {
  const def = _available[cli];
  if (!def) {
    const avail = Object.keys(_available);
    throw new Error(`CLI "${cli}" not available. Available: ${avail.length ? avail.join(', ') : 'none (run detect() first)'}`);
  }

  const args = def.buildArgs(prompt, opts);
  const timeout = opts.timeout || def.defaultTimeout;
  const env = cleanEnvFor(opts);

  try {
    const { stdout, stderr } = await spawnAsync(def.binary, args, {
      timeout,
      env,
      cwd: opts.cwd || process.cwd()
    });

    return {
      cli,
      binary: def.binary,
      success: true,
      output: stdout.trim(),
      stderr: stderr?.trim() || null,
      prompt,
      model: opts.model || 'default'
    };
  } catch (err) {
    if (err.killed) {
      return { cli, success: false, error: `Timeout after ${timeout}ms`, prompt };
    }
    if (err.stdout) {
      return {
        cli,
        success: false,
        output: err.stdout.trim(),
        error: err.stderr?.trim() || err.message,
        prompt
      };
    }
    throw err;
  }
}

// ── Ask multiple CLIs the same question (parallel) ──

export async function consensus(prompt, opts = {}) {
  const clis = opts.clis || Object.keys(_available);
  const results = await Promise.allSettled(
    clis.map(cli => invoke(cli, prompt, opts))
  );

  return clis.map((cli, i) => {
    const r = results[i];
    return r.status === 'fulfilled'
      ? r.value
      : { cli, success: false, error: r.reason?.message || 'Unknown error' };
  });
}

mcp-server/lib/news.js:
/**
 * News & SEC filings tracker
 * Monitors news, SEC EDGAR filings, earnings for watchlist tickers
 * Sends alerts on significant events
 */

import * as cache from './cache.js';

const SEC_BASE = 'https://efts.sec.gov/LATEST/search-index';
const EDGAR_FILINGS = 'https://data.sec.gov/submissions';

// ══════════════════════════════════════
// SEC EDGAR — Filing Search
// ══════════════════════════════════════

export async function getRecentFilings(ticker, types = ['10-K', '10-Q', '8-K', '4'], limit = 10) {
  const key = `sec:${ticker}:${types.join(',')}`;
  const cached = cache.get(key);
  if (cached) return cached;

  try {
    // First get CIK from ticker
    const cik = await getCIK(ticker);
    if (!cik) return { ticker, filings: [], error: 'CIK not found' };

    const url = `${EDGAR_FILINGS}/CIK${cik.padStart(10, '0')}.json`;
    const res = await fetch(url, {
      headers: { 'User-Agent': 'DailyTickers MCP contact@dailytickers.com' }
    });
    if (!res.ok) return { ticker, filings: [] };

    const data = await res.json();
    const recent = data.filings?.recent || {};
    const filings = [];

    const forms = recent.form || [];
    const dates = recent.filingDate || [];
    const descriptions = recent.primaryDocDescription || [];
    const accessions = recent.accessionNumber || [];

    for (let i = 0; i < Math.min(forms.length, 50); i++) {
      if (types.includes(forms[i]) || types.includes('*')) {
        filings.push({
          type: forms[i],
          date: dates[i],
          description: descriptions[i] || '',
          url: `https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=${cik}&type=${forms[i]}&dateb=&owner=include&count=5`,
          accession: accessions[i]
        });
      }
      if (filings.length >= limit) break;
    }

    const result = { ticker, company: data.name, cik, filings };
    cache.set(key, result, 3600); // 1 hour cache
    return result;
  } catch (err) {
    return { ticker, filings: [], error: err.message };
  }
}

async function getCIK(ticker) {
  const key = `cik:${ticker}`;
  const cached = cache.get(key);
  if (cached) return cached;

  try {
    const res = await fetch('https://www.sec.gov/files/company_tickers.json', {
      headers: { 'User-Agent': 'DailyTickers MCP contact@dailytickers.com' }
    });
    const data = await res.json();

    for (const entry of Object.values(data)) {
      if (entry.ticker === ticker.toUpperCase()) {
        const cik = String(entry.cik_str);
        cache.set(key, cik, 86400 * 30); // cache 30 days
        return cik;
      }
    }
    return null;
  } catch {
    return null;
  }
}

// ══════════════════════════════════════
// INSIDER TRANSACTIONS (Form 4)
// ══════════════════════════════════════

export async function getInsiderActivity(ticker) {
  const filings = await getRecentFilings(ticker, ['4'], 20);
  return {
    ticker,
    insiderFilings: filings.filings,
    summary: {
      totalFilings: filings.filings.length,
      recentDays: filings.filings.length > 0 ? daysSince(filings.filings[0].date) : null
    }
  };
}

function daysSince(dateStr) {
  const d = new Date(dateStr);
  return Math.floor((Date.now() - d.getTime()) / 86400000);
}

// ══════════════════════════════════════
// NEWS AGGREGATOR
// ══════════════════════════════════════

export async function aggregateNews(tickers, limit = 5) {
  const allNews = [];

  for (const ticker of tickers) {
    try {
      // Use Yahoo search API for news
      const key = `news:${ticker}`;
      const cached = cache.get(key);
      let news;

      if (cached) {
        news = cached;
      } else {
        const url = `https://query2.finance.yahoo.com/v1/finance/search?q=${ticker}&quotesCount=0&newsCount=${limit}`;
        const res = await fetch(url, {
          headers: { 'User-Agent': 'Mozilla/5.0' }
        });
        if (res.ok) {
          const data = await res.json();
          news = (data.news || []).map(n => ({
            ticker,
            title: n.title,
            publisher: n.publisher,
            link: n.link,
            publishedAt: n.providerPublishTime ? new Date(n.providerPublishTime * 1000).toISOString() : null
          }));
          cache.set(key, news, 300);
        } else {
          news = [];
        }
      }

      allNews.push(...news);
    } catch {
      // skip errors
    }
  }

  // Sort by date descending
  allNews.sort((a, b) => {
    const da = a.publishedAt ? new Date(a.publishedAt) : new Date(0);
    const db = b.publishedAt ? new Date(b.publishedAt) : new Date(0);
    return db - da;
  });

  return allNews;
}

// ══════════════════════════════════════
// NEWS MONITOR (check for new articles)
// ══════════════════════════════════════

const seenUrls = new Set();
let onNewsCallback = null;

export function onNewArticle(callback) {
  onNewsCallback = callback;
}

export async function checkForNewNews(tickers) {
  const news = await aggregateNews(tickers, 3);
  const newArticles = [];

  for (const article of news) {
    if (article.link && !seenUrls.has(article.link)) {
      seenUrls.add(article.link);
      newArticles.push(article);
    }
  }

  if (newArticles.length > 0 && onNewsCallback) {
    for (const article of newArticles) {
      onNewsCallback(article);
    }
  }

  return newArticles;
}

// ══════════════════════════════════════
// EARNINGS CALENDAR
// ══════════════════════════════════════

export async function getUpcomingEarnings(tickers) {
  const results = [];

  for (const ticker of tickers) {
    try {
      const url = `https://query2.finance.yahoo.com/v10/finance/quoteSummary/${ticker}?modules=calendarEvents`;
      const res = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0' } });
      if (!res.ok) continue;

      const data = await res.json();
      const cal = data?.quoteSummary?.result?.[0]?.calendarEvents;
      if (!cal?.earnings) continue;

      const earningsDate = cal.earnings.earningsDate?.[0]?.fmt;
      if (!earningsDate) continue;

      results.push({
        ticker,
        earningsDate,
        epsEstimate: cal.earnings.earningsAverage?.raw,
        revenueEstimate: cal.earnings.revenueAverage?.raw,
        epsTrend: {
          current: cal.earnings.earningsAverage?.raw,
          weekAgo: cal.earnings.earningsAverage?.raw // simplified
        }
      });
    } catch {
      // skip
    }
  }

  // Sort by earnings date
  results.sort((a, b) => new Date(a.earningsDate) - new Date(b.earningsDate));
  return results;
}

